def _records(account_id, mode=None):
    rows = list_game_records(account_id, 5000)
    if mode:
        rows = [r for r in rows if str(r.get('mode', '')).lower() == mode.lower()]
    return rows


def _metric_for(result, key):
    try:
        if key == 'score':
            return float(result.get('score', result.get('total', 0)) or 0)
        if key == 'rank':
            return int(result.get('rank', result.get('place', 99)) or 99)
    except Exception:
        pass
    return 0


def unlock_mode_achievements(account_id, mode, result=None):
    """Unlock mode-specific achievements while keeping the existing Career card format."""
    if not account_id:
        return []
    mode = mode.lower()
    result = result or {}
    rows = _records(account_id, mode)
    count = len(rows) + 1

    # Include the current game in the historical aggregates.
    cur_score = _metric_for(result, 'score')
    cur_rank = _metric_for(result, 'rank')
    synthetic = {
        'result': f'{cur_rank}위' if cur_rank and cur_rank < 99 else '',
        'score': cur_score,
    }
    all_rows = rows + [synthetic]

    def rank_of(r):
        s = str(r.get('result', ''))
        m = re.search(r'(\d+)위', s)
        return int(m.group(1)) if m else 99

    import re
    ranks = [rank_of(r) for r in all_rows]
    scores = []
    for r in all_rows:
        try:
            scores.append(float(r.get('score', 0) or 0))
        except Exception:
            scores.append(0)

    win_count = sum(1 for r in ranks if r == 1)
    top2_count = sum(1 for r in ranks if r <= 2)
    top3_count = sum(1 for r in ranks if r <= 3)

    unlocked = []
    for a in MODE_ACHIEVEMENTS.get(mode, []):
        d = a['desc']
        ok = False

        m = re.search(r'(\d+)회 완료', d)
        if m and count >= int(m.group(1)):
            ok = True

        m = re.search(r'1위 (\d+)회', d)
        if m and win_count >= int(m.group(1)):
            ok = True

        m = re.search(r'2위 이내 (\d+)회', d)
        if m and top2_count >= int(m.group(1)):
            ok = True

        m = re.search(r'3위 이내 (\d+)회', d)
        if m and top3_count >= int(m.group(1)):
            ok = True

        m = re.search(r'(\d+)점 이상 (\d+)회', d)
        if m and sum(1 for x in scores if x >= float(m.group(1))) >= int(m.group(2)):
            ok = True

        m = re.search(r'(\d+)점 이상 1회', d)
        if m and any(x >= float(m.group(1)) for x in scores):
            ok = True

        if ok:
            unlocked.append({
                'id': a['id'],
                'name': a['name'],
                'desc': a['desc'],
                'icon': a['icon']
            })

    return unlock_custom(account_id, unlocked)

def mode_achievement_defs(mode):
    return MODE_ACHIEVEMENTS.get(mode.lower(), [])
